-- Correct Cambridge 9 Test 1; retain question IDs and attempt history.
-- Source: https://engnovate.com/ielts-reading-tests/cambridge-ielts-09-academic-reading-test-1/
begin;
update public.skill_tests set status = 'hidden', updated_at = now() where slug = 'IELTS_Animals_Biology_B1';
do $repair$
declare
  exam_id uuid;
  section_id_value uuid;
  group_id_value uuid;
  group_data jsonb;
  question_data jsonb;
  affected integer;
begin
  select id into exam_id from public.skill_tests where slug = 'cam-9-1';
  if exam_id is null then raise exception 'Missing Cambridge 9 Test 1'; end if;
  if (select count(*) from public.skill_questions q join public.skill_question_groups g on g.id = q.group_id join public.skill_sections s on s.id = g.section_id where s.test_id = exam_id) <> 40 then
    raise exception 'Expected 40 Cambridge 9 Test 1 questions';
  end if;
  -- Free final positions before moving existing questions between groups.
  update public.skill_questions q set order_index = q.source_number + 100
  from public.skill_question_groups g, public.skill_sections s
  where q.group_id = g.id and g.section_id = s.id and s.test_id = exam_id;
  for group_data in select value from jsonb_array_elements($data$[{"section":1,"order":1,"instruction":"<h3>Questions 1–7</h3><p>Do the following statements agree with the information given in Reading Passage 1?</p><p>Write</p><p><strong>TRUE</strong> if the statement agrees with the information</p><p><strong>FALSE</strong> if the statement contradicts the information</p><p><strong>NOT GIVEN</strong> if there is no information on this</p>","display":"tfng","config":{},"questions":[{"number":1,"order":1,"type":"tfng","display":"tfng","html":""},{"number":2,"order":2,"type":"tfng","display":"tfng","html":""},{"number":3,"order":3,"type":"tfng","display":"tfng","html":""},{"number":4,"order":4,"type":"tfng","display":"tfng","html":""},{"number":5,"order":5,"type":"tfng","display":"tfng","html":""},{"number":6,"order":6,"type":"tfng","display":"tfng","html":""},{"number":7,"order":7,"type":"tfng","display":"tfng","html":""}]},{"section":1,"order":2,"instruction":"<h3>Questions 8–13</h3><p>Answer the questions below.</p><p>Choose <strong>NO MORE THAN TWO WORDS</strong> from the passage for each answer.</p>","display":"fill-blank","config":{},"questions":[{"number":8,"order":1,"type":"fill","display":"fill-blank","html":""},{"number":9,"order":2,"type":"fill","display":"fill-blank","html":""},{"number":10,"order":3,"type":"fill","display":"fill-blank","html":""},{"number":11,"order":4,"type":"fill","display":"fill-blank","html":""},{"number":12,"order":5,"type":"fill","display":"fill-blank","html":""},{"number":13,"order":6,"type":"fill","display":"fill-blank","html":""}]},{"section":2,"order":1,"instruction":"<h3>Questions 14–17</h3><p>Reading Passage 2 has five paragraphs, A–E.</p><p>Choose the correct heading for paragraphs B–E from the list of headings below.</p><p>Write the correct number, i–vii.</p>","display":"matching-heading","config":{"headings":["Seeking the transmission of radio signals from planets","Appropriate responses to signals from other civilisations","Vast distances to Earth's closest neighbours","Assumptions underlying the search for extra-terrestrial intelligence","Reasons for the search for extra-terrestrial intelligence","Knowledge of extra-terrestrial life forms","Likelihood of life on other planets"]},"questions":[{"number":14,"order":1,"type":"matching","display":"matching-heading","html":""},{"number":15,"order":2,"type":"matching","display":"matching-heading","html":""},{"number":16,"order":3,"type":"matching","display":"matching-heading","html":""},{"number":17,"order":4,"type":"matching","display":"matching-heading","html":""}]},{"section":2,"order":2,"instruction":"<h3>Questions 18–20</h3><p>Answer the questions below.</p><p>Choose <strong>NO MORE THAN THREE WORDS AND/OR A NUMBER</strong> from the passage for each answer.</p>","display":"fill-blank","config":{},"questions":[{"number":18,"order":1,"type":"fill","display":"fill-blank","html":""},{"number":19,"order":2,"type":"fill","display":"fill-blank","html":""},{"number":20,"order":3,"type":"fill","display":"fill-blank","html":""}]},{"section":2,"order":3,"instruction":"<h3>Questions 21–26</h3><p>Do the following statements agree with the views of the writer in Reading Passage 2?</p><p>Write</p><p><strong>YES</strong> if the statement agrees with the views of the writer</p><p><strong>NO</strong> if the statement contradicts the views of the writer</p><p><strong>NOT GIVEN</strong> if it is impossible to say what the writer thinks about this</p>","display":"ynng","config":{},"questions":[{"number":21,"order":1,"type":"ynng","display":"ynng","html":""},{"number":22,"order":2,"type":"ynng","display":"ynng","html":""},{"number":23,"order":3,"type":"ynng","display":"ynng","html":""},{"number":24,"order":4,"type":"ynng","display":"ynng","html":""},{"number":25,"order":5,"type":"ynng","display":"ynng","html":""},{"number":26,"order":6,"type":"ynng","display":"ynng","html":""}]},{"section":3,"order":1,"instruction":"<h3>Questions 27–30</h3><p>Answer the questions below.</p><p>Choose <strong>NO MORE THAN TWO WORDS</strong> from the passage for each answer.</p>","display":"fill-blank","config":{},"questions":[{"number":27,"order":1,"type":"fill","display":"fill-blank","html":""},{"number":28,"order":2,"type":"fill","display":"fill-blank","html":""},{"number":29,"order":3,"type":"fill","display":"fill-blank","html":""},{"number":30,"order":4,"type":"fill","display":"fill-blank","html":""}]},{"section":3,"order":2,"instruction":"<h3>Questions 31–33</h3><p>Do the following statements agree with the information given in Reading Passage 3?</p><p>Write</p><p><strong>TRUE</strong> if the statement agrees with the information</p><p><strong>FALSE</strong> if the statement contradicts the information</p><p><strong>NOT GIVEN</strong> if there is no information on this</p>","display":"tfng","config":{},"questions":[{"number":31,"order":1,"type":"tfng","display":"tfng","html":""},{"number":32,"order":2,"type":"tfng","display":"tfng","html":""},{"number":33,"order":3,"type":"tfng","display":"tfng","html":""}]},{"section":3,"order":3,"instruction":"<h3>Questions 34–39</h3><p>Complete the flow-chart below.</p><p>Choose <strong>NO MORE THAN TWO WORDS AND/OR A NUMBER</strong> from the passage for each answer.</p>","display":"note-completion","config":{},"questions":[{"number":34,"order":1,"type":"fill","display":"note-completion","html":"<h4>Method of determining where the ancestors of turtles and tortoises come from</h4><p><strong>Step 1</strong></p><p>71 species of living turtles and tortoises were examined and a total of 34_______ were taken from the bones of their forelimbs.</p><p><strong>Step 2</strong></p><p>The data was recorded on a 35_______ (necessary for comparing the information).</p><p>Outcome: Land tortoises were represented by a dense 36_______ of points towards the top.</p><p>Sea turtles were grouped together in the bottom part.</p><p><strong>Step 3</strong></p><p>The same data was collected from some living 37_______ species and added to the other results.</p><p>Outcome: The points for these species turned out to be positioned about 38_______ up the triangle between the land tortoises and the sea turtles.</p><p><strong>Step 4</strong></p><p>Bones of P. quenstedti and P. talampayensis were examined in a similar way and the results added.</p><p>Outcome: The position of the points indicated that both these ancient creatures were 39_______.</p>","answer":"three measurements","accepted":["3 measurements"]},{"number":35,"order":2,"type":"fill","display":"note-completion","html":""},{"number":36,"order":3,"type":"fill","display":"note-completion","html":""},{"number":37,"order":4,"type":"fill","display":"note-completion","html":""},{"number":38,"order":5,"type":"fill","display":"note-completion","html":""},{"number":39,"order":6,"type":"fill","display":"note-completion","html":""}]},{"section":3,"order":4,"instruction":"<h3>Questions 40</h3><p>Choose the correct letter, A, B, C or D.</p>","display":"multiple-choice","config":{},"questions":[{"number":40,"order":1,"type":"mcq","display":"multiple-choice","html":"","prompt":"According to the writer, the most significant thing about tortoises is that","options":["they are able to adapt to life in extremely dry environments.","their original life form was a kind of primeval bacteria.","they have so much in common with sea turtles.","they have made the transition from sea to land more than once."]}]}]$data$::jsonb)
  loop
    select id into strict section_id_value from public.skill_sections where test_id = exam_id and section_no = (group_data->>'section')::integer;
    insert into public.skill_question_groups (section_id, order_index, instruction_html, display_type, config)
    values (section_id_value, (group_data->>'order')::integer, group_data->>'instruction', group_data->>'display', group_data->'config')
    on conflict (section_id, order_index) do update set instruction_html = excluded.instruction_html, display_type = excluded.display_type, config = excluded.config
    returning id into group_id_value;
    for question_data in select value from jsonb_array_elements(group_data->'questions')
    loop
      update public.skill_questions q set
        group_id = group_id_value, order_index = (question_data->>'order')::integer,
        question_type = question_data->>'type', display_type = question_data->>'display',
        question_html = question_data->>'html',
        prompt = coalesce(question_data->>'prompt', q.prompt),
        options = coalesce(question_data->'options', q.options),
        answer_key = coalesce(question_data->>'answer', q.answer_key),
        accepted_answers = case when question_data ? 'accepted' then array(select jsonb_array_elements_text(question_data->'accepted')) else q.accepted_answers end
      from public.skill_question_groups old_group
      where old_group.id = q.group_id and old_group.section_id = section_id_value and q.source_number = (question_data->>'number')::integer;
      get diagnostics affected = row_count;
      if affected <> 1 then raise exception 'Expected one question for %', question_data->>'number'; end if;
    end loop;
  end loop;
end $repair$;
commit;
